Section Cells.
  Variable segs : list Segment.

  Lemma cell_rd_off : forall m TB (cells : list dcell) i c k n,
    bytes_at segs m TB (concat (map fse_cell_bytes cells)) -> nth_error cells (Z.to_nat i) = Some c -> 0 <= i ->
    0 <= k -> k + Z.of_nat n <= 4 ->
    ov_read_bytes segs m (wa (TB + (4 * i + k))) n = Some (firstn n (skipn (Z.to_nat k) (fse_cell_bytes c))).
